<script setup lang="ts">
import {can} from './session'
import WarehouseLabels from './WarehouseLabels.vue'
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('WarehousePanel')

import {ref,reactive,computed,onMounted} from 'vue'
import {ElMessage} from 'element-plus'
import {api,session} from './session'
const admin=computed(()=>can('warehouse','operate'))
const warehouses=ref<any[]>([]),rows=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false),error=ref('')
const labelsOpen=ref(false)
const filters=reactive({q:'',sort_by:'available',sort_order:'desc',warehouse_id:'' as number|string,merge:true,hide_zero:false})
const summary=reactive({available:0,locked:0,pending:0,value:0})
const money=(v:any,d=2)=>v==null?'—':new Intl.NumberFormat('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(v))
const time=(v:string)=>new Date(v).toLocaleString('zh-CN',{hour12:false})
let sequence=0
async function load(){const seq=++sequence;loading.value=true;error.value='';try{const params=new URLSearchParams({q:filters.q,sort_by:filters.sort_by,sort_order:filters.sort_order,merge:String(filters.merge),hide_zero:String(filters.hide_zero),page:String(page.value)});if(filters.warehouse_id)params.set('warehouse_id',String(filters.warehouse_id));const d=await api('/warehouse/stock?'+params);if(seq!==sequence)return;rows.value=d.rows;total.value=d.total;Object.assign(summary,d.summary)}catch(e){if(seq===sequence)error.value=(e as Error).message}finally{if(seq===sequence)loading.value=false}}
function search(){page.value=1;load()}
function reset(){Object.assign(filters,{q:'',sort_by:'available',sort_order:'desc',warehouse_id:'',merge:true,hide_zero:false});search()}
async function options(){warehouses.value=(await api('/warehouse/options')).warehouses}
const warehouseDialog=ref(false),warehouseBusy=ref(false),warehouseError=ref('')
const warehouseForm=reactive({name:'',manager:'',address:''})
function newWarehouse(){Object.assign(warehouseForm,{name:'',manager:'',address:''});warehouseError.value='';warehouseDialog.value=true}
async function saveWarehouse(){if(warehouseBusy.value)return;if(!warehouseForm.name.trim()||!warehouseForm.manager.trim()){warehouseError.value='请填写仓库名称和负责人';return}warehouseBusy.value=true;warehouseError.value='';try{const d=await api('/warehouse/warehouses',warehouseForm);await options();filters.warehouse_id=d.id;warehouseDialog.value=false;search();ElMessage.success('本地仓库已新增')}catch(e){warehouseError.value=(e as Error).message}finally{warehouseBusy.value=false}}
const movementDialog=ref(false),movementBusy=ref(false),movementError=ref(''),context=ref<any>(null),productOptions=ref<any[]>([]),productLoading=ref(false)
const movement=reactive({request_id:'',warehouse_id:null as number|null,product_id:null as number|null,lot_id:null as number|null,kind:'in',quantity:1,unit_cost:null as number|null,note:''})
let productRequest=0
async function findProducts(q:string){const seq=++productRequest;productLoading.value=true;try{const d=await api('/products?'+new URLSearchParams({q,page_size:'30'}));if(seq===productRequest)productOptions.value=d.rows}catch(e){if(seq===productRequest)movementError.value=(e as Error).message}finally{if(seq===productRequest)productLoading.value=false}}
function selectProduct(id:number){const p=productOptions.value.find(p=>p.id===id);movement.unit_cost=p?.cost_cny==null?null:Number(p.cost_cny)}
function newRequestId(){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);bytes[6]=(bytes[6]!&15)|64;bytes[8]=(bytes[8]!&63)|128;const h=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`}
async function openMovement(kind:string,row?:any){context.value=row||null;Object.assign(movement,{request_id:newRequestId(),warehouse_id:row?.warehouse_id||Number(filters.warehouse_id)||warehouses.value[0]?.id||null,product_id:row?.product_id||null,lot_id:kind==='out'?row?.lot_id||null:null,kind,quantity:1,unit_cost:null,note:''});movementError.value='';movementDialog.value=true;if(!row){await findProducts('')}else if(kind==='in'){try{const p=await api('/products/'+row.product_id);movement.unit_cost=p.cost_cny==null?null:Number(p.cost_cny)}catch(e){movementError.value=(e as Error).message}}}
let submittedFingerprint=''
async function saveMovement(){if(movementBusy.value)return;if(!movement.warehouse_id||!movement.product_id||!Number.isInteger(movement.quantity)||movement.quantity<1){movementError.value='请选择仓库、标品并填写正整数数量';return}if(movement.kind==='in'&&(movement.unit_cost==null||movement.unit_cost<0)){movementError.value='请填写采购单价，无成本时可明确填0';return}const fingerprint=JSON.stringify({...movement,request_id:''});if(submittedFingerprint&&submittedFingerprint!==fingerprint)movement.request_id=newRequestId();submittedFingerprint=fingerprint;movementBusy.value=true;movementError.value='';try{await api('/warehouse/movements',movement);movementDialog.value=false;ElMessage.success(movement.kind==='in'?'入库已完成':'出库已完成');await load()}catch(e){movementError.value=(e as Error).message}finally{movementBusy.value=false}}
const logDialog=ref(false),logRows=ref<any[]>([]),logTotal=ref(0),logPage=ref(1),logContext=ref<any>(null),logLoading=ref(false),logError=ref('')
async function openLogs(row:any){logContext.value=row;logPage.value=1;logDialog.value=true;await loadLogs()}
async function loadLogs(){logLoading.value=true;logError.value='';try{const r=logContext.value;const p=new URLSearchParams({warehouse_id:String(r.warehouse_id),product_id:String(r.product_id),page:String(logPage.value)});if(r.lot_id)p.set('lot_id',String(r.lot_id));const d=await api('/warehouse/logs?'+p);logRows.value=d.rows;logTotal.value=d.total}catch(e){logError.value=(e as Error).message}finally{logLoading.value=false}}
onMounted(async()=>{try{await options();await load()}catch(e){error.value=(e as Error).message}})
</script>
<template>
<div class="warehouse-panel">
 <div class="warehouse-toolbar"><el-select v-model="filters.warehouse_id" aria-label="仓库筛选" placeholder="全部仓库" clearable :value-on-clear="''" @change="search"><el-option v-for="w in warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select></div>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <div class="warehouse-summary"><div><span>可用量</span><strong>{{money(summary.available,0)}}</strong></div><div><span>可用锁定量</span><strong>{{money(summary.locked,0)}}</strong></div><div><span>待到货量</span><strong>{{money(summary.pending,0)}}</strong></div><div><span>在库货值 · 人民币</span><strong>¥{{money(summary.value)}}</strong></div></div>
 <section class="panel">
 <form class="warehouse-filters" @submit.prevent="search"><el-input v-model="filters.q" placeholder="搜索标品编码 / 中文品名" clearable/><el-button type="primary" native-type="submit">查询</el-button><el-select v-model="filters.sort_by" aria-label="库存排序字段" style="width:120px"><el-option value="available" label="可用量"/><el-option value="locked" label="锁定量"/><el-option value="pending" label="待到货量"/></el-select><el-select v-model="filters.sort_order" aria-label="库存排序方向" style="width:100px"><el-option value="desc" label="降序"/><el-option value="asc" label="升序"/></el-select><el-button @click="reset">重置</el-button><el-button @click="load">刷新库存</el-button><el-button v-if="admin" type="primary" @click="openMovement('in')">新增入库</el-button><el-button type="primary" plain @click="labelsOpen=true">打印FNSKU标签</el-button><span class="stock-display-options"><el-checkbox v-model="filters.merge" @change="search">同仓相同SKU合并显示</el-checkbox><el-checkbox v-model="filters.hide_zero" @change="search">隐藏0库存数据</el-checkbox></span><TableReset table-key="WarehousePanel/table-1"/></form>
 <div class="warehouse-note muted">SKU 指商品中心的标品编码。未合并时按入库批次展示；合并单价按在库数量加权平均，货值包含锁定库存。隐藏0库存仍保留待到货记录。</div>
 <template v-if="true"><el-table border data-width-key="WarehousePanel/table-1" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-1', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-1', column, event)" :data="rows" v-loading="loading" :row-key="(r:any)=>`${r.warehouse_id}:${r.product_id}:${r.lot_id||0}`" style="width:100%" empty-text="暂无库存记录，可先新增仓库，再为标品登记入库">
 <el-table-column :column-key="'column-1'" label="图片" :width="tableWidths.width('table-1', 'column-1', '85')"><template #default="{row}"><el-image v-if="row.image_url" :src="row.image_url" fit="contain" class="stock-image"><template #error><span class="muted">暂无图片</span></template></el-image><span v-else class="muted">暂无图片</span></template></el-table-column>
 <el-table-column :column-key="'column-2'" :width="tableWidths.width('table-1', 'column-2', undefined)" label="标品编码 / 品名" min-width="280"><template #default="{row}"><strong>{{row.code}}</strong><div>{{row.name}}</div><small class="muted">{{row.lot_id?(row.source==='purchase_pending'?'采购待到货':`入库批次 #${row.lot_id}`):`合并 ${row.batches} 条库存记录`}}<span v-if="row.reference"> · {{row.reference}}</span><span v-if="row.archived"> · 标品已归档</span></small></template></el-table-column>
 <el-table-column :column-key="'warehouse_name'" :width="tableWidths.width('table-1', 'warehouse_name', undefined)" prop="warehouse_name" label="仓库" min-width="140"/>
 <el-table-column :column-key="'available'" prop="available" label="可用量" :width="tableWidths.width('table-1', 'available', '115')" align="right"/>
 <el-table-column :column-key="'locked'" prop="locked" label="可用锁定量" :width="tableWidths.width('table-1', 'locked', '120')" align="right"/>
 <el-table-column :column-key="'pending'" prop="pending" label="待到货量" :width="tableWidths.width('table-1', 'pending', '115')" align="right"/>
 <el-table-column :column-key="'column-7'" label="采购单价 (¥)" :width="tableWidths.width('table-1', 'column-7', '145')" align="right"><template #default="{row}">{{money(row.unit_cost,4)}}</template></el-table-column>
 <el-table-column :column-key="'column-8'" label="货值 (¥)" :width="tableWidths.width('table-1', 'column-8', '150')" align="right"><template #default="{row}">{{money(row.value)}}</template></el-table-column>
 <el-table-column :column-key="'column-9'" label="操作" :width="tableWidths.width('table-1', 'column-9', '185')" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="!admin||row.available<=0" @click="openMovement('out',row)">出库</el-button><span class="muted">｜</span><el-button link type="primary" :disabled="!admin||row.archived" @click="openMovement('in',row)">入库</el-button><span class="muted">｜</span><el-button link type="primary" @click="openLogs(row)">日志</el-button></template></el-table-column>
 </el-table></template>
 <div class="stock-footer"><span>筛选合计：可用 {{money(summary.available,0)}} · 锁定 {{money(summary.locked,0)}} · 待到货 {{money(summary.pending,0)}} · 货值 ¥{{money(summary.value)}}</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total, prev, pager, next" @current-change="load"/></div>
 </section>
 <p class="warehouse-note muted">数量按标品销售包装计数，例如 -6P 标品入库 1 表示 1 包。待到货量来自采购单的待到货余量；采购单登记到货后自动入库。锁定量由发货计划预留，删除计划后释放；未到货部分到货后补锁。{{!admin?'当前账号可查看；新增仓库及出入库由管理员操作。':''}}</p>

 <el-dialog v-model="warehouseDialog" title="新增本地仓库" width="520px" :close-on-click-modal="false" :show-close="!warehouseBusy" :close-on-press-escape="!warehouseBusy">
 <el-alert v-if="warehouseError" :title="warehouseError" type="error" :closable="false"/>
 <el-form label-position="top" :disabled="warehouseBusy"><el-form-item label="仓库名称" required><el-input v-model="warehouseForm.name" placeholder="例如：深圳仓" maxlength="120"/></el-form-item><el-form-item label="负责人" required><el-input v-model="warehouseForm.manager" placeholder="填写负责人姓名" maxlength="120"/></el-form-item><el-form-item label="仓库地址（选填）"><el-input v-model="warehouseForm.address" type="textarea" :rows="3" maxlength="1000"/></el-form-item></el-form>
 <template #footer><el-button :disabled="warehouseBusy" @click="warehouseDialog=false">取消</el-button><el-button type="primary" :loading="warehouseBusy" @click="saveWarehouse">保存仓库</el-button></template></el-dialog>
 <el-dialog v-model="movementDialog" :title="movement.kind==='in'?'入库登记':'出库登记'" width="600px" :close-on-click-modal="false" :show-close="!movementBusy" :close-on-press-escape="!movementBusy">
 <el-alert v-if="movementError" :title="movementError" type="error" :closable="false"/>
 <el-form label-position="top" :disabled="movementBusy"><el-form-item label="仓库" required><el-select v-model="movement.warehouse_id" :disabled="!!context" style="width:100%"><el-option v-for="w in warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select></el-form-item>
 <div v-if="context" class="movement-product"><strong>{{context.code}}</strong><p>{{context.name}}</p><span>可用量 {{context.available}} {{context.lot_id?`· 批次 #${context.lot_id}`:''}}</span></div>
 <el-form-item v-else label="标品" required><el-select v-model="movement.product_id" filterable remote :remote-method="findProducts" :loading="productLoading" placeholder="搜索标品编码或中文品名" style="width:100%" @change="selectProduct"><el-option v-for="p in productOptions" :key="p.id" :value="p.id" :label="`${p.code} · ${p.name}`"/></el-select></el-form-item>
 <el-form-item :label="movement.kind==='in'?'入库数量':'出库数量'" required><el-input-number v-model="movement.quantity" :min="1" :max="movement.kind==='out'?context?.available:10000000" :precision="0"/></el-form-item>
 <el-form-item v-if="movement.kind==='in'" label="采购单价（人民币 / 标品包装）" required><el-input-number v-model="movement.unit_cost" :min="0" :max="100000000" :precision="4" :step="0.1"/><span class="muted"> 默认取商品中心成本，可修改本次入库单价</span></el-form-item>
 <p class="muted">{{movement.kind==='in'?'每次入库生成独立批次，不覆盖商品中心的采购成本。':movement.lot_id?'从当前批次扣减可用库存。':'按先入先出扣减同仓同标品的可用库存，锁定库存不可出库。'}}</p>
 <el-form-item label="备注 / 单据号"><el-input v-model="movement.note" type="textarea" :rows="3" maxlength="1000" show-word-limit/></el-form-item></el-form>
 <template #footer><el-button :disabled="movementBusy" @click="movementDialog=false">取消</el-button><el-button type="primary" :loading="movementBusy" @click="saveMovement">{{movement.kind==='in'?'确认入库':'确认出库'}}</el-button></template></el-dialog>
 <el-dialog v-model="logDialog" title="库存操作日志" width="min(1050px, 94vw)"><p v-if="logContext"><strong>{{logContext.code}}</strong> · {{logContext.name}} · {{logContext.warehouse_name}}</p><el-alert v-if="logError" :title="logError" type="error" :closable="false"/>
 <template v-if="true"><TableReset table-key="WarehousePanel/table-2"/><el-table border data-width-key="WarehousePanel/table-2" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-2', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-2', column, event)" :data="logRows" v-loading="logLoading" empty-text="暂无操作日志"><el-table-column :column-key="'column-1'" label="时间" :width="tableWidths.width('table-2', 'column-1', '180')"><template #default="{row}">{{time(row.created_at)}}</template></el-table-column><el-table-column :column-key="'column-2'" label="操作" :width="tableWidths.width('table-2', 'column-2', '85')"><template #default="{row}"><el-tag :type="row.kind==='in'?'success':'warning'">{{row.kind==='in'?'入库':'出库'}}</el-tag></template></el-table-column><el-table-column :column-key="'column-3'" label="数量" :width="tableWidths.width('table-2', 'column-3', '80')"><template #default="{row}">{{row.kind==='in'?'+':'−'}}{{row.quantity}}</template></el-table-column><el-table-column :column-key="'column-4'" label="货值 (¥)" :width="tableWidths.width('table-2', 'column-4', '110')"><template #default="{row}">{{money(row.cost)}}</template></el-table-column><el-table-column :column-key="'actor'" prop="actor" label="操作人" :width="tableWidths.width('table-2', 'actor', '120')"/><el-table-column :column-key="'column-6'" :width="tableWidths.width('table-2', 'column-6', undefined)" label="批次变化" min-width="180"><template #default="{row}"><div v-for="a in row.detail.allocations" :key="a.lot_id">#{{a.lot_id}}：{{a.before}} → {{a.after}}<small>（¥{{money(a.unit_cost,4)}}）</small></div></template></el-table-column><el-table-column :column-key="'note'" :width="tableWidths.width('table-2', 'note', undefined)" prop="note" label="备注" min-width="160"/></el-table></template><el-pagination v-model:current-page="logPage" :total="logTotal" :page-size="20" layout="total, prev, pager, next" @current-change="loadLogs"/>
 </el-dialog>
</div>
<WarehouseLabels :open="labelsOpen" @close="labelsOpen=false"/></template>
<style scoped>
.warehouse-toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;gap:16px}.warehouse-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-bottom:22px}.warehouse-summary>div{background:white;border:1px solid #e2e9e5;border-radius:12px;padding:24px;display:flex;flex-direction:column;gap:12px}.warehouse-summary span,.muted{color:#899b92}.warehouse-summary strong{font-size:27px;color:#293e36}.warehouse-filters{display:flex;flex-wrap:wrap;gap:14px;align-items:center;padding:22px}.warehouse-filters>.el-input{flex:1;min-width:240px}.warehouse-filters>.el-select{width:180px}.warehouse-note{font-size:12px;line-height:1.8;padding:0 22px 16px}.stock-image{width:54px;height:54px;border-radius:6px}.stock-footer{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap;padding:20px;color:#567366;font-size:13px}.warehouse-directory{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px}.warehouse-directory>div{padding:20px;border:1px solid #e2e9e5;border-radius:10px;display:flex;flex-direction:column;gap:8px;background:white;font-size:13px}.warehouse-directory span{color:#82968c}.movement-product{background:#f0f7f3;border-radius:8px;padding:16px;margin-bottom:20px}.warehouse-panel :deep(.el-form-item){margin-top:18px}.warehouse-panel :deep(.el-table .cell){line-height:1.8}.warehouse-panel :deep(.el-pagination){margin-top:12px}@media(max-width:900px){.warehouse-summary{grid-template-columns:repeat(2,1fr)}.warehouse-toolbar{align-items:flex-start;flex-direction:column}}
</style>

<style scoped>.warehouse-filters>.el-input{flex:0 0 250px;min-width:0}.warehouse-filters{flex-wrap:wrap}.warehouse-toolbar>.el-select{width:240px}</style>

<style scoped>.stock-display-options{display:flex;gap:16px;align-items:center}.stock-display-options .el-checkbox{margin-right:0}.stock-display-options :deep(.el-checkbox__label){font-size:13px;font-weight:400;padding-left:6px}</style>
